steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    query {
      issues(filter: {
        title: {contains: \"login timeout\"},
        createdAt: {between: [\"2025-06-03T00:00:00.000Z\", \"2025-06-03T23:59:59.999Z\"]}
      }) {
        nodes {
          id
          title
          priority
          team {
            name
          }
          createdAt
          user {
            name
          }
        }
      }
    }
  "
  }'
